import { YardPlan, YARD_PLAN_CAPTION, YARD_PLAN_LOURDES_NOTE } from "@/components/yard-plan";
import { FigureEnlarge } from "@/components/figure-enlarge";
import { FallbackImage } from "@/components/fallback-image";
import { assets, shipyard } from "@/lib/site-content";

/*
 * Shipyard section: our shipyard at Fomar, Shiroda, Goa, where Lourdes will be built.
 *
 *  1. Hero visual: the illustrative aerial render (blender/yard, own Blender model), full bleed.
 *  2. Schematic site plan (components/yard-plan.tsx, generated by blender/yard/scripts/make_yard_plan.py)
 *     beside the annotated figures and the illustrative berth view.
 * Both renders show Lourdes as she will be built and are captioned as illustrations (SOURCE_CONFLICTS
 * YD-8); the plan is captioned as a schematic and opens larger in a dialog. A render that fails to load leaves
 * its navy placeholder (FallbackImage). `assets.yardRender = false` leaves the plan and figures only.
 */
export function ShipyardSection() {
  const r = shipyard.render;
  const b = shipyard.berthView;
  return (
    <section className="shipyard section" id="shipyard" aria-labelledby="shipyard-title">
      <div className="wrap">
        <div className="section-heading shipyard-heading">
          <div>
            <p className="eyebrow">{shipyard.eyebrow}</p>
            <h2 id="shipyard-title">{shipyard.title}</h2>
          </div>
          <div className="shipyard-lead">
            <span className="tag">{shipyard.status}</span>
            <p>{shipyard.lead}</p>
          </div>
        </div>
      </div>

      {assets.yardRender && (
        <figure className="shipyard-render">
          <FallbackImage src={r.src} srcSet={r.srcSet} sizes="100vw" alt={r.alt} width={r.width} height={r.height} loading="lazy" decoding="async" />
          <figcaption>{r.caption}</figcaption>
        </figure>
      )}

      <div className="wrap shipyard-grid">
        <div className="shipyard-plan-col">
          <h3 className="detail-title">{shipyard.planTitle}</h3>
          <figure className="shipyard-plan">
            <YardPlan />
            <figcaption>
              <span>{YARD_PLAN_CAPTION}</span>
              <span>{YARD_PLAN_LOURDES_NOTE}</span>
              <FigureEnlarge title="Our shipyard / Site plan" description={YARD_PLAN_CAPTION}>
                <YardPlan tone="light" />
              </FigureEnlarge>
            </figcaption>
          </figure>
        </div>
        <div className="shipyard-aside">
          <div className="shipyard-facts">
            <h3 className="detail-title">{shipyard.factsTitle}</h3>
            <dl className="spec-table spec-table--compact">
              {shipyard.facts.map(f => (
                <div key={f.label}>
                  <dt>{f.label}</dt>
                  <dd>
                    {f.value}
                    {f.note && <small>{f.note}</small>}
                  </dd>
                </div>
              ))}
            </dl>
            <p className="source-note">{shipyard.source}</p>
          </div>
          {assets.yardRender && (
            <figure className="shipyard-berth">
              <FallbackImage src={b.src} srcSet={b.srcSet} sizes="(max-width: 760px) 100vw, (max-width: 1100px) 50vw, 440px" alt={b.alt} width={b.width} height={b.height} loading="lazy" decoding="async" />
              <figcaption>{b.caption}</figcaption>
            </figure>
          )}
        </div>
      </div>
    </section>
  );
}
